// tools/launch_gen.dart — deterministic splash/launch-image generator.
//
// Derives every native splash image from the app-icon source asset so a
// future icon update is ONE re-run:
//
//   dart run tools/launch_gen.dart
//
// Reads:  assets/icons/app_icon_foreground.png  (1024x1024 RGBA — the icon
//         artwork on transparency, generated by tools/icon_gen.dart)
//
// Writes (always byte-identical — integer box-filter scaling, no RNG):
//   Android API 31+ system-splash icon, artwork at ~45% of the density canvas
//   (transparent padding so the OS splash renders it small — matching iOS):
//     android/app/src/main/res/drawable-mdpi/launch_image.png    120px canvas /  54px art
//     android/app/src/main/res/drawable-hdpi/launch_image.png    180px canvas /  81px art
//     android/app/src/main/res/drawable-xhdpi/launch_image.png   240px canvas / 108px art
//     android/app/src/main/res/drawable-xxhdpi/launch_image.png  360px canvas / 162px art
//     android/app/src/main/res/drawable-xxxhdpi/launch_image.png 480px canvas / 216px art
//   iOS launch-screen icon, full-canvas (contentMode=center in the storyboard,
//   so the pixel size IS the point size):
//     ios/Runner/Assets.xcassets/LaunchImage.imageset/LaunchImage.png     96x96
//     ios/Runner/Assets.xcassets/LaunchImage.imageset/LaunchImage@2x.png  192x192
//     ios/Runner/Assets.xcassets/LaunchImage.imageset/LaunchImage@3x.png  288x288
//
// Pure Dart on purpose (mirrors tools/icon_gen.dart): no package deps, a
// minimal PNG decoder (RGBA, all scanline filters) + a premultiplied-alpha
// box-filter scaler + the hand-rolled PNG encoder. Runs anywhere.

import 'dart:io';
import 'dart:typed_data';

const String _iconPath = 'assets/icons/app_icon_foreground.png';

// Android density canvases (px = dp) and the artwork size inside each.
const List<({String density, int canvas, double artRatio})> _android = [
  (density: 'mdpi', canvas: 120, artRatio: 0.45),
  (density: 'hdpi', canvas: 180, artRatio: 0.45),
  (density: 'xhdpi', canvas: 240, artRatio: 0.45),
  (density: 'xxhdpi', canvas: 360, artRatio: 0.45),
  (density: 'xxxhdpi', canvas: 480, artRatio: 0.45),
];

// iOS full-canvas launch images (pixel size = point size, @1x/@2x/@3x).
const List<({String file, int size})> _ios = [
  (file: 'LaunchImage.png', size: 96),
  (file: 'LaunchImage@2x.png', size: 192),
  (file: 'LaunchImage@3x.png', size: 288),
];

// ── Minimal PNG decoder (RGBA in, all scanline filters) ──────────────────────

const List<int> _signature = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];

({int width, int height, Uint8List rgba}) _decodePng(String path) {
  final bytes = File(path).readAsBytesSync();
  if (bytes.length < 8 ||
      !_listEquals(bytes.sublist(0, 8), _signature)) {
    throw StateError('$path is not a PNG');
  }
  int width = 0;
  int height = 0;
  int colorType = -1;
  final idat = BytesBuilder();
  var off = 8;
  while (off < bytes.length) {
    final len = ByteData.sublistView(bytes, off, off + 4).getUint32(0);
    final type = String.fromCharCodes(bytes.sublist(off + 4, off + 8));
    final data = bytes.sublist(off + 8, off + 8 + len);
    switch (type) {
      case 'IHDR':
        width = ByteData.sublistView(data).getUint32(0);
        height = ByteData.sublistView(data).getUint32(4);
        colorType = data[9];
      case 'IDAT':
        idat.add(data);
      case 'IEND':
        break;
    }
    off += 12 + len;
  }
  if (colorType != 6 && colorType != 2) {
    throw StateError('$path: unsupported PNG color type $colorType '
        '(need 2=RGB or 6=RGBA)');
  }
  final bpp = colorType == 6 ? 4 : 3;
  final raw = ZLibCodec().decode(idat.toBytes());

  // Un-filter scanlines (filters 0..4).
  final stride = width * bpp;
  final out = Uint8List(width * height * 4);
  final prev = Uint8List(stride);
  for (var y = 0; y < height; y++) {
    final filter = raw[y * (stride + 1)];
    final line = raw.sublist(y * (stride + 1) + 1, (y + 1) * (stride + 1));
    for (var x = 0; x < stride; x++) {
      final a = x >= bpp ? line[x - bpp] : 0;
      final b = prev[x];
      final c = x >= bpp ? prev[x - bpp] : 0;
      final p = switch (filter) {
        0 => line[x],
        1 => line[x] + a,
        2 => line[x] + b,
        3 => line[x] + ((a + b) >> 1),
        4 => line[x] + _paeth(a, b, c),
        _ => throw StateError('$path: bad scanline filter $filter'),
      };
      final v = p & 0xFF;
      final dst = y * width * 4 + x ~/ bpp * 4 + (x % bpp);
      out[dst] = v;
      prev[x] = v;
    }
  }
  // RGB -> RGBA (alpha 255); RGBA passthrough.
  if (colorType == 2) {
    final rgba = Uint8List(width * height * 4);
    for (var i = 0; i < width * height; i++) {
      rgba[i * 4] = out[i * 3];
      rgba[i * 4 + 1] = out[i * 3 + 1];
      rgba[i * 4 + 2] = out[i * 3 + 2];
      rgba[i * 4 + 3] = 255;
    }
    return (width: width, height: height, rgba: rgba);
  }
  return (width: width, height: height, rgba: out);
}

int _paeth(int a, int b, int c) {
  final p = a + b - c;
  final pa = (p - a).abs();
  final pb = (p - b).abs();
  final pc = (p - c).abs();
  if (pa <= pb && pa <= pc) return a;
  if (pb <= pc) return b;
  return c;
}

bool _listEquals(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

// ── Premultiplied-alpha box-filter scaling ───────────────────────────────────

/// Downscale/upscale [src] (w*h*4 straight RGBA) to dw*dh via box averaging.
/// RGB is premultiplied by alpha before averaging and unpremultiplied after,
/// so transparent pixels never bleed dark fringes into the edges of the art.
Uint8List _boxScale(Uint8List src, int w, int h, int dw, int dh) {
  final dst = Uint8List(dw * dh * 4);
  for (var dy = 0; dy < dh; dy++) {
    final y0 = dy * h ~/ dh;
    final y1 = ((dy + 1) * h + dh - 1) ~/ dh;
    for (var dx = 0; dx < dw; dx++) {
      final x0 = dx * w ~/ dw;
      final x1 = ((dx + 1) * w + dw - 1) ~/ dw;
      var r = 0.0, g = 0.0, b = 0.0, a = 0.0;
      for (var sy = y0; sy < y1; sy++) {
        for (var sx = x0; sx < x1; sx++) {
          final o = (sy * w + sx) * 4;
          final sa = src[o + 3];
          r += src[o] * sa;
          g += src[o + 1] * sa;
          b += src[o + 2] * sa;
          a += sa;
        }
      }
      final n = (x1 - x0) * (y1 - y0);
      final o = (dy * dw + dx) * 4;
      if (a > 0) {
        dst[o] = (r / a).round().clamp(0, 255);
        dst[o + 1] = (g / a).round().clamp(0, 255);
        dst[o + 2] = (b / a).round().clamp(0, 255);
        dst[o + 3] = (a / n).round().clamp(0, 255);
      } else {
        dst[o + 3] = 0;
      }
    }
  }
  return dst;
}

/// Centered paste of [art] (aw*ah RGBA) into a [canvas]x[canvas] transparent
/// frame. Returns the frame RGBA.
Uint8List _centerOnCanvas(Uint8List art, int aw, int ah, int canvas) {
  final frame = Uint8List(canvas * canvas * 4);
  final ox = (canvas - aw) ~/ 2;
  final oy = (canvas - ah) ~/ 2;
  for (var y = 0; y < ah; y++) {
    for (var x = 0; x < aw; x++) {
      final s = (y * aw + x) * 4;
      final d = ((y + oy) * canvas + (x + ox)) * 4;
      frame[d] = art[s];
      frame[d + 1] = art[s + 1];
      frame[d + 2] = art[s + 2];
      frame[d + 3] = art[s + 3];
    }
  }
  return frame;
}

// ── Minimal PNG encoder (RGBA, filter 0, zlib level 9) — from icon_gen ──────

Uint8List _png(Uint8List rgba, int width, int height) {
  final raw = BytesBuilder();
  final stride = width * 4;
  for (var y = 0; y < height; y++) {
    raw.addByte(0); // filter: None
    raw.add(rgba.sublist(y * stride, (y + 1) * stride));
  }
  final compressed = ZLibCodec(level: 9).encode(raw.toBytes());

  final crcTable = _crc32Table();
  final out = BytesBuilder()..add(_signature);

  void chunk(String type, List<int> data) {
    final len = ByteData(4)..setUint32(0, data.length);
    out.add(len.buffer.asUint8List());
    final typeBytes = type.codeUnits;
    out.add(typeBytes);
    out.add(data);
    final crc = ByteData(4)
      ..setUint32(
        0,
        _crc32(crcTable, [...typeBytes, ...data]) & 0xFFFFFFFF,
      );
    out.add(crc.buffer.asUint8List());
  }

  final ihdr = ByteData(13)
    ..setUint32(0, width, Endian.big)
    ..setUint32(4, height, Endian.big)
    ..setUint8(8, 8)
    ..setUint8(9, 6) // color type RGBA
    ..setUint8(10, 0)
    ..setUint8(11, 0)
    ..setUint8(12, 0);
  chunk('IHDR', ihdr.buffer.asUint8List());
  chunk('IDAT', compressed);
  chunk('IEND', const []);
  return out.toBytes();
}

List<int> _crc32Table() {
  final table = List<int>.filled(256, 0);
  for (var n = 0; n < 256; n++) {
    var c = n;
    for (var k = 0; k < 8; k++) {
      c = (c & 1) == 1 ? 0xEDB88320 ^ (c >> 1) : c >> 1;
    }
    table[n] = c;
  }
  return table;
}

int _crc32(List<int> table, List<int> bytes) {
  var c = 0xFFFFFFFF;
  for (final byte in bytes) {
    c = table[(c ^ byte) & 0xFF] ^ (c >> 8);
  }
  return c ^ 0xFFFFFFFF;
}

// ── Main ─────────────────────────────────────────────────────────────────────

Future<void> main() async {
  if (!File(_iconPath).existsSync()) {
    stderr.writeln('source icon missing: $_iconPath — run tools/icon_gen.dart '
        'first');
    exit(1);
  }
  final icon = _decodePng(_iconPath);

  // Android: scaled artwork centered on a density canvas (45% fill).
  for (final spec in _android) {
    final artSize = (spec.canvas * spec.artRatio).round();
    final art = _boxScale(icon.rgba, icon.width, icon.height, artSize, artSize);
    final frame = _centerOnCanvas(art, artSize, artSize, spec.canvas);
    final out =
        'android/app/src/main/res/drawable-${spec.density}/launch_image.png';
    await File(out).writeAsBytes(
      _png(frame, spec.canvas, spec.canvas),
      flush: true,
    );
    stdout.writeln(
      'wrote $out (${spec.canvas}x${spec.canvas} canvas / ${artSize}x$artSize art)',
    );
  }

  // iOS: full-canvas launch images (art fills the image; contentMode=center).
  for (final spec in _ios) {
    final scaled = _boxScale(
      icon.rgba,
      icon.width,
      icon.height,
      spec.size,
      spec.size,
    );
    final out =
        'ios/Runner/Assets.xcassets/LaunchImage.imageset/${spec.file}';
    await File(out).writeAsBytes(
      _png(scaled, spec.size, spec.size),
      flush: true,
    );
    stdout.writeln('wrote $out (${spec.size}x${spec.size})');
  }
}
